// @FIGURE_CODE_BEGIN
/* ─── ELEMENT SPEC ────────────────────────────────────────────────────────────
 // grey constant block 4x4x512 → BoxGeometry(4.0,2.2,1.7)  #c3ccd2 / side #4b5b64 / top #d9e0e4 + EdgesGeometry
 // orange conv block 4x4x512   → BoxGeometry(3.6,2.2,1.7)  #cf8066 / #a85c45 / #e09a80 + edges
 // orange conv block 8x8x512   → BoxGeometry(4.2,3.6,2.8)  same tints (x2)
 // cyan noise slab             → ExtrudeGeometry(roundedRect 0.28x2.2 / 0.32x3.6, depth 1.7 / 2.8) #a8ddd2 + edges
 // dark AdaIN slab             → same extrude, #3f6480 + edges
 // output RGB image            → BoxGeometry(0.1,3.2,2.6), +X face = 8x8 CanvasTexture of browns/tans
 // noise map planes            → BoxGeometry(0.08,1.6,1.7) / (0.08,3.2,2.8), +X face = 4x4 / 8x8 cyan CanvasTexture
 // latent bar z                → BoxGeometry(2.1,0.30,0.55) #9bb6c8
 // intermediate bar w          → BoxGeometry(2.1,0.30,0.55) #cf8066
 // linear-transform bars (x3)  → BoxGeometry(2.4,0.34,0.60) #cf8066
 // noise arrows (x3)           → Cylinder + Cone, #a9c0cc, pointing down
 // style arrows (x3, x3 bus)   → Cylinder + Cone, #4c6d84, pointing up
 // bus line                    → Cylinder along x, #4c6d84
 // FC arrow                    → small Cylinder + Cone, black
 // row braces (x3)             → two CubicBezierCurve3 TubeGeometry, black
 // flow pulses                 → SphereGeometry(0.15) travelling polylines
 ────────────────────────────────────────────────────────────────────────────── */

const COL = {
  oF: 0xcf8066, oS: 0xa85c45, oT: 0xe09a80,
  gF: 0xc3ccd2, gS: 0x4b5b64, gT: 0xd9e0e4,
  cF: 0xa8ddd2, cS: 0x7fc3b5, cT: 0xc5e9e1,
  sF: 0x3f6480, sS: 0x2c4a60, sT: 0x547d9b,
  zF: 0x9bb6c8, zS: 0x6b8ea5, zT: 0xb6cbd9,
  arr: 0x4c6d84, narr: 0xa9c0cc, ink: 0x151515
};

/* ── registry for dimming ───────────────────────────────────────────── */
const REG = [];
function reg(obj, tags) { REG.push({ obj, tags: tags || [] }); return obj; }

function matFace(c, extra) {
  return new THREE.MeshBasicMaterial(Object.assign({
    color: c, polygonOffset: true, polygonOffsetFactor: 1, polygonOffsetUnits: 1
  }, extra || {}));
}
function edgeLines(geo) {
  return new THREE.LineSegments(new THREE.EdgesGeometry(geo, 25),
    new THREE.LineBasicMaterial({ color: COL.ink }));
}

function box(x, y, z, w, h, d, f, s, t) {
  const geo = new THREE.BoxGeometry(w, h, d);
  const mats = [matFace(s), matFace(s), matFace(t), matFace(t), matFace(f), matFace(f)];
  const g = new THREE.Group();
  const mesh = new THREE.Mesh(geo, mats);
  g.add(mesh); g.add(edgeLines(geo));
  g.position.set(x, y, z);
  scene.add(g);
  g.userData.mats = mats;
  return g;
}

function roundedRect(w, h, r) {
  const s = new THREE.Shape();
  const x = -w / 2, y = -h / 2;
  s.moveTo(x + r, y);
  s.lineTo(x + w - r, y); s.quadraticCurveTo(x + w, y, x + w, y + r);
  s.lineTo(x + w, y + h - r); s.quadraticCurveTo(x + w, y + h, x + w - r, y + h);
  s.lineTo(x + r, y + h); s.quadraticCurveTo(x, y + h, x, y + h - r);
  s.lineTo(x, y + r); s.quadraticCurveTo(x, y, x + r, y);
  return s;
}
function slab(x, y, z, w, h, d, f, s) {
  const geo = new THREE.ExtrudeGeometry(roundedRect(w, h, Math.min(w, h) * 0.45),
    { depth: d, bevelEnabled: false, curveSegments: 6 });
  geo.translate(0, 0, -d / 2);
  const mats = [matFace(f), matFace(s)];
  const g = new THREE.Group();
  g.add(new THREE.Mesh(geo, mats));
  g.add(edgeLines(geo));
  g.position.set(x, y, z);
  scene.add(g);
  g.userData.mats = mats;
  return g;
}

function seg(from, to, color, r) {
  const dir = new THREE.Vector3().subVectors(to, from);
  const len = dir.length(); dir.normalize();
  const m = new THREE.Mesh(new THREE.CylinderGeometry(r, r, len, 10), matFace(color));
  const g = new THREE.Group();
  m.position.y = len / 2; g.add(m);
  g.position.copy(from);
  g.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), dir);
  scene.add(g); return g;
}
function arrow(from, to, color, r, hl, hr) {
  r = r || 0.045; hl = hl || 0.36; hr = hr || 0.15;
  const dir = new THREE.Vector3().subVectors(to, from);
  const len = dir.length(); dir.normalize();
  const shaftLen = Math.max(0.01, len - hl);
  const g = new THREE.Group();
  const sh = new THREE.Mesh(new THREE.CylinderGeometry(r, r, shaftLen, 10), matFace(color));
  sh.position.y = shaftLen / 2;
  const hd = new THREE.Mesh(new THREE.ConeGeometry(hr, hl, 16), matFace(color));
  hd.position.y = shaftLen + hl / 2;
  g.add(sh); g.add(hd);
  g.position.copy(from);
  g.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), dir);
  scene.add(g); return g;
}

function brace(x, y0, y1, w) {
  const ym = (y0 + y1) / 2;
  const V = (a, b) => new THREE.Vector3(a, b, 0);
  const cs = [
    new THREE.CubicBezierCurve3(V(x + w, y1), V(x + w * 0.42, y1), V(x + w * 0.58, ym), V(x, ym)),
    new THREE.CubicBezierCurve3(V(x, ym), V(x + w * 0.58, ym), V(x + w * 0.42, y0), V(x + w, y0))
  ];
  const g = new THREE.Group();
  cs.forEach(c => g.add(new THREE.Mesh(new THREE.TubeGeometry(c, 40, 0.035, 6, false), matFace(COL.ink))));
  scene.add(g); return g;
}

/* ── canvas textures ────────────────────────────────────────────────── */
function noiseTex(n) {
  const cv = document.createElement('canvas'); cv.width = cv.height = n;
  const ctx = cv.getContext('2d');
  const vals = []; for (let i = 0; i < n * n; i++) vals.push(Math.random());
  const tex = new THREE.CanvasTexture(cv);
  tex.magFilter = THREE.NearestFilter; tex.minFilter = THREE.NearestFilter;
  function draw(amp) {
    const a = Math.min(1, amp / 1.4);
    for (let j = 0; j < n; j++) for (let i = 0; i < n; i++) {
      const v = 0.5 + (vals[j * n + i] - 0.5) * a;
      const r = Math.round(236 + (108 - 236) * v);
      const g = Math.round(250 + (196 - 250) * v);
      const b = Math.round(246 + (182 - 246) * v);
      ctx.fillStyle = `rgb(${r},${g},${b})`; ctx.fillRect(i, j, 1, 1);
    }
    tex.needsUpdate = true;
  }
  draw(1);
  return { tex, draw };
}
function imgTex(n) {
  const cv = document.createElement('canvas'); cv.width = cv.height = n;
  const ctx = cv.getContext('2d');
  const base = [], jit = [];
  for (let i = 0; i < n * n; i++) { base.push(Math.random()); jit.push(Math.random()); }
  const ramp = [[46, 29, 18], [96, 62, 38], [150, 108, 70], [206, 170, 120], [242, 227, 200]];
  const tex = new THREE.CanvasTexture(cv);
  tex.magFilter = THREE.NearestFilter; tex.minFilter = THREE.NearestFilter;
  function draw(p) {
    for (let j = 0; j < n; j++) for (let i = 0; i < n; i++) {
      const k = j * n + i;
      let v = base[k] + (jit[k] - 0.5) * 0.55 * Math.min(2, p) / 2;
      v = Math.max(0, Math.min(0.999, v));
      const f = v * (ramp.length - 1), i0 = Math.floor(f), t = f - i0;
      const c0 = ramp[i0], c1 = ramp[Math.min(ramp.length - 1, i0 + 1)];
      ctx.fillStyle = `rgb(${Math.round(c0[0] + (c1[0] - c0[0]) * t)},${Math.round(c0[1] + (c1[1] - c0[1]) * t)},${Math.round(c0[2] + (c1[2] - c0[2]) * t)})`;
      ctx.fillRect(i, j, 1, 1);
    }
    tex.needsUpdate = true;
  }
  draw(1);
  return { tex, draw };
}

