    0x2e5f80, 0.12 + i * 0.03, 0.55, 0.12);
});
// noise branches
[[X.c1, 3.5, 1.3], [X.c2, 3.5, 1.3], [X.c3, 3.4, 2.7]].forEach((c, i) => {
  mkPulse([V(c[0], c[1], 0.3), V(c[0], c[2], 0.3)], 0x53c2ab, 0.30 + i * 0.05, 0.35, 0.12);
});
function updatePulses(t, on) {
  pulses.forEach(p => {
    if (!on) { p.m.visible = false; return; }
    const u = (t - p.phase) / p.span;
    if (u < 0 || u > 1) { p.m.visible = false; return; }
    p.m.visible = true;
    p.m.position.copy(pathAt(p, u));
  });
}

