/* ── dimming ────────────────────────────────────────────────────────── */
function setDim(obj, factor) {
  obj.traverse(o => {
    if (!o.material) return;
    const ms = Array.isArray(o.material) ? o.material : [o.material];
    ms.forEach(m => {
      if (m.userData.base === undefined) m.userData.base = m.opacity;
      const op = m.userData.base * factor;
      m.opacity = op;
      m.transparent = op < 0.995;
    });
  });
}
let clickFocus = null, stageIdx = 0;
const STAGES = ['idle', 'z to w', 'linear transforms', 'style into 4x4', 'noise into 4x4',
  'upsample to 8x8', 'style+noise into 8x8', 'output image'];
const STAGE_TAGS = {
  'idle': null,
  'z to w': ['map'],
  'linear transforms': ['map', 'bus', 'bar1', 'bar2', 'bar3', 'styles'],
  'style into 4x4': ['b0', 'bar1', 'sarrow1', 'dark1', 'style1'],
  'noise into 4x4': ['b0', 'b1', 'noise1', 'noise2'],
  'upsample to 8x8': ['b1', 'b2'],
  'style+noise into 8x8': ['b2', 'b3', 'col3'],
  'output image': ['b3', 'out']
};
function applyFocus() {
  const tags = clickFocus || STAGE_TAGS[STAGES[stageIdx]];
  const set = tags ? new Set(tags) : null;
  REG.forEach(e => {
    const on = !set || e.tags.some(t => set.has(t));
    setDim(e.obj, on ? 1 : 0.16);
  });
}

/* ── psi ────────────────────────────────────────────────────────────── */
const cyanSlabs = [cyan1, cyan2, cyan3];
function lerpC(a, b, t) { return new THREE.Color(a).lerp(new THREE.Color(b), t); }
let psiCur = 1, psiTarget = 1, pulseGlow = 0;
function applyPsi(p) {
  // solid teal at psi >= 1; transparency is reserved for low psi only
  const op = Math.max(0, Math.min(1, 0.25 + 0.75 * p));
  noisePlanes.forEach(np => {
    np.userData.nt.draw(p);
    np.userData.mats.forEach(m => { m.userData.base = op; });
  });
  const k = Math.min(1, p);
  const hot = Math.max(0, Math.min(1, (p - 1))) * 0.7 + pulseGlow * 0.5;
  cyanSlabs.forEach(s => {
    const f = lerpC(0xcbd0d0, COL.cF, k).lerp(new THREE.Color(0x5fd6bc), Math.min(1, hot));
    const sd = lerpC(0xa8adad, COL.cS, k).lerp(new THREE.Color(0x36b098), Math.min(1, hot));
    s.userData.mats[0].color.copy(f);
    s.userData.mats[1].color.copy(sd);
  });
  OUT.draw(p);
  applyFocus();
}

/* ── flow pulses ────────────────────────────────────────────────────── */
const pulses = [];
function mkPulse(pts, color, phase, span, r) {
  const m = new THREE.Mesh(new THREE.SphereGeometry(r || 0.15, 12, 10),
    new THREE.MeshBasicMaterial({ color }));
  m.position.copy(pts[0]); m.visible = false; scene.add(m);
  const cum = [0]; let tot = 0;
  for (let i = 1; i < pts.length; i++) { tot += pts[i].distanceTo(pts[i - 1]); cum.push(tot); }
  pulses.push({ m, pts, cum, tot, phase, span });
}
function pathAt(p, u) {
