}

/* ── flow pulses ────────────────────────────────────────────────────── */
const pulses = [];
function mkPulse(pts, color, phase, span, r) {
  const m = new THREE.Mesh(new THREE.SphereGeometry(r || 0.15, 12, 10),
    new THREE.MeshBasicMaterial({ color }));
  m.position.copy(pts[0]); m.visible = false; scene.add(m);
  const cum = [0]; let tot = 0;
  for (let i = 1; i < pts.length; i++) { tot += pts[i].distanceTo(pts[i - 1]); cum.push(tot); }
  pulses.push({ m, pts, cum, tot, phase, span });
}
function pathAt(p, u) {
  const s = Math.max(0, Math.min(1, u)) * p.tot;
  for (let i = 1; i < p.pts.length; i++) {
    if (s <= p.cum[i] || i === p.pts.length - 1) {
      const dd = p.cum[i] - p.cum[i - 1] || 1;
      return p.pts[i - 1].clone().lerp(p.pts[i], Math.max(0, Math.min(1, (s - p.cum[i - 1]) / dd)));
    }
  }
  return p.pts[p.pts.length - 1].clone();
}
