function updatePulses(t, on) {
  pulses.forEach(p => {
    if (!on) { p.m.visible = false; return; }
    const u = (t - p.phase) / p.span;
    if (u < 0 || u > 1) { p.m.visible = false; return; }
    p.m.visible = true;
    p.m.position.copy(pathAt(p, u));
  });
}

