  stageIdx = Math.max(0, Math.min(STAGES.length - 1, i));
  stageSel.value = String(stageIdx);
  applyFocus();
}
stageSel.addEventListener('change', () => {
  clickFocus = null; document.getElementById('focusMsg').textContent = 'no block focused';
  setStage(parseInt(stageSel.value, 10));
});
document.getElementById('stagePrev').addEventListener('click', () => { clickFocus = null; setStage(stageIdx - 1); });
document.getElementById('stageNext').addEventListener('click', () => { clickFocus = null; setStage(stageIdx + 1); });
document.getElementById('clearFocus').addEventListener('click', () => {
  clickFocus = null; document.getElementById('focusMsg').textContent = 'no block focused'; applyFocus();
});
psiSlider.addEventListener('input', () => {
  psiTarget = parseFloat(psiSlider.value); psiCur = psiTarget;
  psiVal.textContent = psiCur.toFixed(2); applyPsi(psiCur);
});
let playing = false;
playBtn.addEventListener('click', () => {
  playing = !playing;
  playBtn.textContent = playing ? '❚❚ Pause data flow' : '▶ Play data flow';
  if (!playing) updatePulses(0, false);
});

/* ── guided demo ────────────────────────────────────────────────────── */
const STEPS = [
  { t: 'Mapping network', n: 'The latent <b>z</b> (1×1×512) passes through the fully connected network to give the intermediate variable <b>w</b> (1×1×512). Nothing in the image trunk has moved yet.', s: 1, p: 1 },
  { t: 'One w, three styles', n: '<b>w</b> fans out along the bottom bus into three separate linear transforms, each producing a 2×1×512 style vector y₁, y₂, y₃ — one scale and one offset per channel.', s: 2, p: 1 },
  { t: 'Style modulates 4×4', n: 'y₁ rises into the dark AdaIN slab and rescales every channel of the learned 4×4×512 constant. Global appearance is set here, not by any pixel-level input.', s: 3, p: 1 },
  { t: 'Noise injected at 4×4', n: 'A single 4×4×1 noise map z₁, scaled by ψ₁, is broadcast to all 512 channels of the cyan slab — the same random field added to every channel.', s: 4, p: 1 },
  { t: 'Up to 8×8', n: 'The block doubles in spatial resolution to 8×8×512, so the matching noise map becomes 8×8×1 while the style vector stays 2×1×512.', s: 5, p: 1 },
  { t: 'Turn the noise off', n: 'Drop ψ to zero: the noise planes fade out and only the style path drives the network — coarse content survives, fine stochastic detail disappears.', s: 6, p: 0 },
  { t: 'Crank the noise up', n: 'At ψ = 2 the noise maps and the cyan slabs they feed light up strongly; stochastic variation dominates the final 8×8×512 features and the output image.', s: 7, p: 2 }
];
let demoIdx = -1, demoTimer = null, demoRunning = false;
function goToStep(i) {
  demoIdx = (i + STEPS.length) % STEPS.length;
  const st = STEPS[demoIdx];
  clickFocus = null;
  document.getElementById('focusMsg').textContent = 'no block focused';
  setStage(st.s);
  psiTarget = st.p;
  psiSlider.value = String(st.p);
  narrT.innerHTML = `${demoIdx + 1}/${STEPS.length} &middot; ${st.t}`;
  narrB.innerHTML = st.n;
}
function stopDemo() {
  demoRunning = false; clearTimeout(demoTimer);
  document.getElementById('demoBtn').textContent = '▶ Run guided demo';
}
function runDemo() {
  if (!demoRunning) return;
  goToStep(demoIdx + 1);
  demoTimer = setTimeout(runDemo, 5200);
}
document.getElementById('demoBtn').addEventListener('click', () => {
  if (demoRunning) { stopDemo(); return; }
  demoRunning = true; demoIdx = -1;
  document.getElementById('demoBtn').textContent = '❚❚ Stop demo';
  runDemo();
});
document.getElementById('demoPrev').addEventListener('click', () => { stopDemo(); goToStep(demoIdx - 1); });
document.getElementById('demoNext').addEventListener('click', () => { stopDemo(); goToStep(demoIdx + 1); });

/* ── local update loop (scaffold renders) ───────────────────────────── */
let _t = 0, _last = performance.now();
function tick(now) {
  requestAnimationFrame(tick);
  const dt = Math.min(0.06, (now - _last) / 1000); _last = now;
  let need = false;
  if (Math.abs(psiCur - psiTarget) > 0.004) {
    psiCur += (psiTarget - psiCur) * Math.min(1, dt * 5);
    psiSlider.value = String(psiCur);
    psiVal.textContent = psiCur.toFixed(2);
    need = true;
  } else if (psiCur !== psiTarget) {
    psiCur = psiTarget; psiVal.textContent = psiCur.toFixed(2); need = true;
  }
  if (playing) {
    _t = (_t + dt / 4.5) % 1;
    updatePulses(_t, true);
    const g = Math.max(0, Math.sin((_t - 0.3) * Math.PI / 0.45)) * Math.min(1, psiCur);
    if (Math.abs(g - pulseGlow) > 0.02) { pulseGlow = g; need = true; }
  }
  if (need) applyPsi(psiCur);
}
requestAnimationFrame(tick);

applyPsi(1);
applyFocus();
// @FIGURE_CODE_END

Fix all identified failure modes and improve every score. Maintain or improve what already works well.
Return ONLY the updated marker-wrapped payload.

