// @FIGURE_CODE_BEGIN
/* ─── ELEMENT SPEC (one line per element) ─────────────────────────────────────
 // grey constant block 4x4x512 → BoxGeometry(2.90,1.32,1.60)  #c3ccd2 front / #4b5b64 side / #d9e0e4 top + black edges
 // orange conv block 4x4x512   → BoxGeometry(2.90,1.32,1.60)  #cf8066 / #a85c45 / #e09a80 + edges
 // orange conv blocks 8x8x512  → BoxGeometry(2.90,2.45,2.90)  same tints (x2), centred y=+0.63
 // cyan noise slab             → ExtrudeGeometry(roundedRect 0.46x1.45 | 0.58x2.60, depth 1.60|2.90) #a8ddd2 + edges
 // dark AdaIN slab             → ExtrudeGeometry same profile, #3f6480 + edges
 // output RGB plate (detached) → BoxGeometry(0.12,3.20,3.00), ±X faces = 8x8 CanvasTexture brown/tan
 // noise map planes            → BoxGeometry(0.07,1.20,1.45) | (0.07,2.40,2.80), ±X face = teal CanvasTexture
 // latent bar z                → BoxGeometry(2.52,0.26,0.50) #9bb6c8
 // intermediate bar w          → BoxGeometry(2.52,0.26,0.50) #cf8066
 // linear-transform bars (x3)  → BoxGeometry(2.52,0.35,0.55) #cf8066
 // noise arrows (x3)           → Cylinder + Cone, #a9c0cc, pointing down
 // style arrows (x3) + bus (x3)→ Cylinder + Cone, #4c6d84, pointing up
 // bus line                    → Cylinder along x, #4c6d84
 // FC arrow                    → small Cylinder + Cone, black
 // row braces (x3)             → two CubicBezierCurve3 TubeGeometry, black
 // flow pulses                 → SphereGeometry travelling polylines
 ────────────────────────────────────────────────────────────────────────────── */

const COL = {
  oF: 0xcf8066, oS: 0xa85c45, oT: 0xe09a80,
  gF: 0xc3ccd2, gS: 0x4b5b64, gT: 0xd9e0e4,
  cF: 0xa8ddd2, cS: 0x6fb9a9, cT: 0xc9ebe3,
  sF: 0x3f6480, sS: 0x2c4a60, sT: 0x547d9b,
  zF: 0x9bb6c8, zS: 0x6b8ea5, zT: 0xb6cbd9,
  arr: 0x4c6d84, narr: 0xa9c0cc, ink: 0x1d1d1d
};

const REG = [];
function reg(obj, tags) { REG.push({ obj, tags: tags || [] }); return obj; }

function matFace(c, extra) {
  return new THREE.MeshBasicMaterial(Object.assign({
    color: c, polygonOffset: true, polygonOffsetFactor: 1, polygonOffsetUnits: 1
  }, extra || {}));
}
function edgeLines(geo) {
  return new THREE.LineSegments(new THREE.EdgesGeometry(geo, 25),
    new THREE.LineBasicMaterial({ color: COL.ink }));
}
function box(x, y, z, w, h, d, f, s, t) {
  const geo = new THREE.BoxGeometry(w, h, d);
  const mats = [matFace(s), matFace(s), matFace(t), matFace(t), matFace(f), matFace(f)];
  const g = new THREE.Group();
  g.add(new THREE.Mesh(geo, mats));
  g.add(edgeLines(geo));
  g.position.set(x, y, z);
  scene.add(g);
  g.userData.mats = mats;
  return g;
}
function roundedRect(w, h, r) {
  const s = new THREE.Shape();
  const x = -w / 2, y = -h / 2;
  s.moveTo(x + r, y);
  s.lineTo(x + w - r, y); s.quadraticCurveTo(x + w, y, x + w, y + r);
  s.lineTo(x + w, y + h - r); s.quadraticCurveTo(x + w, y + h, x + w - r, y + h);
  s.lineTo(x + r, y + h); s.quadraticCurveTo(x, y + h, x, y + h - r);
  s.lineTo(x, y + r); s.quadraticCurveTo(x, y, x + r, y);
  return s;
}
function slab(x, y, z, w, h, d, f, s) {
  const geo = new THREE.ExtrudeGeometry(roundedRect(w, h, Math.min(w, h) * 0.45),
    { depth: d, bevelEnabled: false, curveSegments: 10 });
  geo.translate(0, 0, -d / 2);
  const mats = [matFace(f), matFace(s)];
  const g = new THREE.Group();
  g.add(new THREE.Mesh(geo, mats));
  g.add(edgeLines(geo));
  g.position.set(x, y, z);
  scene.add(g);
  g.userData.mats = mats;
  return g;
}
function seg(from, to, color, r) {
  const dir = new THREE.Vector3().subVectors(to, from);
  const len = dir.length(); dir.normalize();
  const m = new THREE.Mesh(new THREE.CylinderGeometry(r, r, len, 10), matFace(color));
  const g = new THREE.Group();
  m.position.y = len / 2; g.add(m);
  g.position.copy(from);
  g.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), dir);
  scene.add(g); return g;
}
function arrow(from, to, color, r, hl, hr) {
  r = r || 0.04; hl = hl || 0.30; hr = hr || 0.13;
  const dir = new THREE.Vector3().subVectors(to, from);
  const len = dir.length(); dir.normalize();
  const shaftLen = Math.max(0.01, len - hl);
  const g = new THREE.Group();
  const sh = new THREE.Mesh(new THREE.CylinderGeometry(r, r, shaftLen, 10), matFace(color));
  sh.position.y = shaftLen / 2;
  const hd = new THREE.Mesh(new THREE.ConeGeometry(hr, hl, 16), matFace(color));
  hd.position.y = shaftLen + hl / 2;
  g.add(sh); g.add(hd);
  g.position.copy(from);
  g.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), dir);
  scene.add(g); return g;
}
function brace(x, y0, y1, w) {
  const ym = (y0 + y1) / 2;
  const V2 = (a, b) => new THREE.Vector3(a, b, 0);
  const cs = [
    new THREE.CubicBezierCurve3(V2(x + w, y1), V2(x + w * 0.42, y1), V2(x + w * 0.58, ym), V2(x, ym)),
    new THREE.CubicBezierCurve3(V2(x, ym), V2(x + w * 0.58, ym), V2(x + w * 0.42, y0), V2(x + w, y0))
  ];
  const g = new THREE.Group();
  cs.forEach(c => g.add(new THREE.Mesh(new THREE.TubeGeometry(c, 44, 0.035, 6, false), matFace(COL.ink))));
  scene.add(g); return g;
}

/* ── canvas textures ────────────────────────────────────────────────── */
function noiseTex(n) {
  const cv = document.createElement('canvas'); cv.width = cv.height = n;
  const ctx = cv.getContext('2d');
  const vals = []; for (let i = 0; i < n * n; i++) vals.push(Math.random());
  const tex = new THREE.CanvasTexture(cv);
  tex.magFilter = THREE.NearestFilter; tex.minFilter = THREE.NearestFilter;
  const LO = [104, 182, 166], HI = [206, 240, 232];
  function draw(amp) {
    const a = Math.min(1, amp / 1.3);
    for (let j = 0; j < n; j++) for (let i = 0; i < n; i++) {
      const v = 0.5 + (vals[j * n + i] - 0.5) * a;
      const r = Math.round(LO[0] + (HI[0] - LO[0]) * v);
      const g = Math.round(LO[1] + (HI[1] - LO[1]) * v);
      const b = Math.round(LO[2] + (HI[2] - LO[2]) * v);
      ctx.fillStyle = `rgb(${r},${g},${b})`; ctx.fillRect(i, j, 1, 1);
    }
    tex.needsUpdate = true;
  }
  draw(1);
  return { tex, draw };
}
function imgTex(n) {
  const cv = document.createElement('canvas'); cv.width = cv.height = n;
  const ctx = cv.getContext('2d');
  const base = [], jit = [];
  for (let i = 0; i < n * n; i++) { base.push(Math.random()); jit.push(Math.random()); }
  const ramp = [[46, 29, 18], [96, 62, 38], [150, 108, 70], [206, 170, 120], [244, 230, 205]];
  const tex = new THREE.CanvasTexture(cv);
  tex.magFilter = THREE.NearestFilter; tex.minFilter = THREE.NearestFilter;
  function draw(p) {
    for (let j = 0; j < n; j++) for (let i = 0; i < n; i++) {
      const k = j * n + i;
      let v = base[k] + (jit[k] - 0.5) * 0.55 * Math.min(2, p) / 2;
      v = Math.max(0, Math.min(0.999, v));
      const f = v * (ramp.length - 1), i0 = Math.floor(f), t = f - i0;
      const c0 = ramp[i0], c1 = ramp[Math.min(ramp.length - 1, i0 + 1)];
      ctx.fillStyle = `rgb(${Math.round(c0[0] + (c1[0] - c0[0]) * t)},${Math.round(c0[1] + (c1[1] - c0[1]) * t)},${Math.round(c0[2] + (c1[2] - c0[2]) * t)})`;
      ctx.fillRect(i, j, 1, 1);
    }
    tex.needsUpdate = true;
  }
  draw(1);
  return { tex, draw };
}

/* ── layout constants (world units, 1 unit ≈ 69.5 px of the source) ─── */
const WB = 2.90;                       // trunk block width (512 channels)
const H4 = 1.32, D4 = 1.60;            // 4×4 spatial extent
const H8 = 2.45, D8 = 2.90, Y8 = 0.63; // 8×8 spatial extent (bottom aligned)
const SW4 = 0.46, SH4 = 1.45;
const SW8 = 0.58, SH8 = 2.60;
const X = {
  grey: 1.45, c1: 3.55, d1: 4.27, o1: 6.37, c2: 8.47, d2: 9.19,
  b1: 11.29, c3: 13.45, d3: 14.29, b2: 16.45, img: 18.80,
  z: -2.10, w: 1.80
};
const YBAR = -3.78, YBUS = -6.13, YZW = -6.07;
const V = (a, b, c) => new THREE.Vector3(a, b, c || 0);

/* ── main pipeline ──────────────────────────────────────────────────── */
const greyBlk = reg(box(X.grey, 0, 0, WB, H4, D4, COL.gF, COL.gS, COL.gT), ['b0', 'trunk']);
const cyan1 = reg(slab(X.c1, 0, 0, SW4, SH4, D4, COL.cF, COL.cS), ['cyan1', 'col1', 'noise1']);
const dark1 = reg(slab(X.d1, 0, 0, SW4, SH4, D4, COL.sF, COL.sS), ['dark1', 'col1', 'style1']);
const orange1 = reg(box(X.o1, 0, 0, WB, H4, D4, COL.oF, COL.oS, COL.oT), ['b1', 'trunk']);
const cyan2 = reg(slab(X.c2, 0, 0, SW4, SH4, D4, COL.cF, COL.cS), ['cyan2', 'col2', 'noise2']);
const dark2 = reg(slab(X.d2, 0, 0, SW4, SH4, D4, COL.sF, COL.sS), ['dark2', 'col2', 'style2']);
const big1 = reg(box(X.b1, Y8, 0, WB, H8, D8, COL.oF, COL.oS, COL.oT), ['b2', 'trunk']);
const cyan3 = reg(slab(X.c3, Y8, 0, SW8, SH8, D8, COL.cF, COL.cS), ['cyan3', 'col3', 'noise3']);
const dark3 = reg(slab(X.d3, Y8, 0, SW8, SH8, D8, COL.sF, COL.sS), ['dark3', 'col3', 'style3']);
const big2 = reg(box(X.b2, Y8, 0, WB, H8, D8, COL.oF, COL.oS, COL.oT), ['b3', 'trunk']);

/* output RGB plate — detached, enlarged, pixel texture on the receding face */
const OUT = imgTex(8);
const outGeo = new THREE.BoxGeometry(0.12, 3.20, 3.00);
const outMats = [
  matFace(0xffffff, { map: OUT.tex }), matFace(0xffffff, { map: OUT.tex }),
  matFace(0xc9a678), matFace(0x8c6a4a), matFace(0xb08a5e), matFace(0x8c6a4a)
];
const outGrp = new THREE.Group();
outGrp.add(new THREE.Mesh(outGeo, outMats));
outGrp.add(edgeLines(outGeo));
outGrp.position.set(X.img, Y8, 0);
scene.add(outGrp);
reg(outGrp, ['out']);

/* ── noise planes ───────────────────────────────────────────────────── */
function noisePlane(x, y, h, dz, n) {
  const NT = noiseTex(n);
  const geo = new THREE.BoxGeometry(0.07, h, dz);
  const mats = [
    matFace(0xffffff, { map: NT.tex }), matFace(0xffffff, { map: NT.tex }),
    matFace(COL.cT), matFace(COL.cS),
    matFace(COL.cF), matFace(COL.cS)
  ];
  const g = new THREE.Group();
  g.add(new THREE.Mesh(geo, mats));
  g.add(edgeLines(geo));
  g.position.set(x, y, 0);
  scene.add(g);
  g.userData.mats = mats; g.userData.nt = NT;
  return g;
}
const np1 = reg(noisePlane(X.c1, 4.19, 1.20, 1.45, 4), ['np1', 'col1', 'noise1']);
const np2 = reg(noisePlane(X.c2, 4.19, 1.20, 1.45, 4), ['np2', 'col2', 'noise2']);
const np3 = reg(noisePlane(X.c3, 4.99, 2.40, 2.80, 8), ['np3', 'col3', 'noise3']);
const noisePlanes = [np1, np2, np3];

/* noise arrows (down into the cyan slabs) */
reg(arrow(V(X.c1, 3.45), V(X.c1, 0.86), COL.narr, 0.04, 0.30, 0.13), ['narrow1', 'col1', 'noise1']);
reg(arrow(V(X.c2, 3.45), V(X.c2, 0.86), COL.narr, 0.04, 0.30, 0.13), ['narrow2', 'col2', 'noise2']);
reg(arrow(V(X.c3, 3.60), V(X.c3, 2.05), COL.narr, 0.04, 0.30, 0.13), ['narrow3', 'col3', 'noise3']);

/* ── style row ──────────────────────────────────────────────────────── */
reg(box(X.d1, YBAR, 0, 2.52, 0.35, 0.55, COL.oF, COL.oS, COL.oT), ['bar1', 'col1', 'style1', 'styles']);
reg(box(X.d2, YBAR, 0, 2.52, 0.35, 0.55, COL.oF, COL.oS, COL.oT), ['bar2', 'col2', 'style2', 'styles']);
reg(box(X.d3, YBAR, 0, 2.52, 0.35, 0.55, COL.oF, COL.oS, COL.oT), ['bar3', 'col3', 'style3', 'styles']);
reg(arrow(V(X.d1, -3.56), V(X.d1, -0.78), COL.arr, 0.04, 0.30, 0.13), ['sarrow1', 'col1', 'style1']);
reg(arrow(V(X.d2, -3.56), V(X.d2, -0.78), COL.arr, 0.04, 0.30, 0.13), ['sarrow2', 'col2', 'style2']);
reg(arrow(V(X.d3, -3.56), V(X.d3, -0.78), COL.arr, 0.04, 0.30, 0.13), ['sarrow3', 'col3', 'style3']);
reg(seg(V(X.w + 1.26, YBUS), V(X.d3, YBUS), COL.arr, 0.033), ['bus']);
reg(arrow(V(X.d1, YBUS), V(X.d1, -4.02), COL.arr, 0.04, 0.28, 0.12), ['bus', 'bar1', 'col1', 'styles']);
reg(arrow(V(X.d2, YBUS), V(X.d2, -4.02), COL.arr, 0.04, 0.28, 0.12), ['bus', 'bar2', 'col2', 'styles']);
reg(arrow(V(X.d3, YBUS), V(X.d3, -4.02), COL.arr, 0.04, 0.28, 0.12), ['bus', 'bar3', 'col3', 'styles']);

/* mapping network */
reg(box(X.z, YZW, 0, 2.52, 0.26, 0.50, COL.zF, COL.zS, COL.zT), ['map']);
reg(box(X.w, YZW, 0, 2.52, 0.26, 0.50, COL.oF, COL.oS, COL.oT), ['map', 'bus']);
reg(arrow(V(-0.35, -5.22), V(0.25, -5.80), COL.ink, 0.026, 0.20, 0.085), ['map']);

/* row braces (never dimmed) */
brace(-4.40, 3.45, 8.00, 0.45);
brace(-4.40, -1.55, 3.20, 0.45);
brace(-4.40, -7.85, -2.95, 0.45);

/* invisible framing anchors so the outer HTML labels are never cropped */
function anchor(x, y) {
  const m = new THREE.Mesh(new THREE.SphereGeometry(0.02, 4, 3),
    new THREE.MeshBasicMaterial({ transparent: true, opacity: 0, depthWrite: false }));
  m.position.set(x, y, 0); scene.add(m); return m;
}
anchor(-7.90, 0); anchor(20.40, 0); anchor(0, 8.55); anchor(0, -8.55);

/* ── camera (after all geometry) ────────────────────────────────────── */
setCameraView({ projection: 'oblique', obliqueAngleDeg: 45, depthScale: 0.5, rollDeg: 0, heightFraction: 0.94 });

/* ── labels ─────────────────────────────────────────────────────────── */
