/* ── local update loop (scaffold does the rendering) ────────────────── */
let _t = 0, _last = performance.now();
function tick(now) {
  requestAnimationFrame(tick);
  const dt = Math.min(0.06, (now - _last) / 1000); _last = now;
  let need = false;
  if (Math.abs(psiCur - psiTarget) > 0.004) {
    psiCur += (psiTarget - psiCur) * Math.min(1, dt * 5);
    psiSlider.value = String(psiCur);
    psiVal.textContent = psiCur.toFixed(2);
    need = true;
  } else if (psiCur !== psiTarget) {
    psiCur = psiTarget; psiVal.textContent = psiCur.toFixed(2); need = true;
  }
  if (playing) {
    _t = (_t + dt / 4.5) % 1;
    updatePulses(_t, true);
    const g = Math.max(0, Math.sin((_t - 0.3) * Math.PI / 0.45)) * Math.min(1, psiCur);
    if (Math.abs(g - pulseGlow) > 0.02) { pulseGlow = g; need = true; }
  }
  if (need) applyPsi(psiCur);
}
requestAnimationFrame(tick);

applyPsi(1);
